export interface AdkContent {
    role?: string;
    parts?: AdkPart[];
}

export interface AdkEvent {
    content?: AdkContent;
    partial?: boolean;
    turnComplete?: boolean;
    finishReason?: string;
    errorCode?: string;
    errorMessage?: string;
    id?: string;
    invocationId?: string;
    author?: string;
    actions?: {
        skipSummarization?: boolean;
        transferToAgent?: string;
        escalate?: boolean;
        requestedAuthConfigs?: {
            [callId: string]: JsonValue;
        };
        requestedToolConfirmations?: {
            [callId: string]: {
                hint?: string;
                confirmed?: boolean;
                payload?: JsonValue;
            };
        };
        stateDelta?: {
            [k: string]: JsonValue;
        };
        artifactDelta?: {
            [k: string]: JsonValue;
        };
        renderUiWidgets?: Array<{
            name?: string;
            code?: string;
        }>;
        agentState?: JsonValue;
        endOfAgent?: boolean;
    };
    usageMetadata?: {
        promptTokenCount?: number;
        candidatesTokenCount?: number;
        totalTokenCount?: number;
        cachedContentTokenCount?: number;
        thoughtsTokenCount?: number;
        toolUsePromptTokenCount?: number;
        responseTokenCount?: number;
        promptTokensDetails?: JsonValue;
        responseTokensDetails?: JsonValue;
    };
    safetyRatings?: Array<{
        category?: string;
        probability?: string;
        score?: number;
        blocked?: boolean;
    }>;
    promptFeedback?: {
        blockReason?: string;
        safetyRatings?: Array<{
            category?: string;
            probability?: string;
            score?: number;
            blocked?: boolean;
        }>;
    };
    groundingMetadata?: {
        groundingChunks?: Array<{
            web?: {
                uri?: string;
                title?: string;
            };
        }>;
        groundingSupports?: Array<{
            groundingChunkIndices?: number[];
            confidenceScores?: number[];
            segment?: {
                startIndex?: number;
                endIndex?: number;
                text?: string;
            };
        }>;
        searchEntryPoint?: {
            renderedContent?: string;
        };
    };
    citationMetadata?: {
        citations?: Array<{
            uri?: string;
            title?: string;
            startIndex?: number;
            endIndex?: number;
        }>;
    };
    interrupted?: boolean;
    longRunningToolIds?: string[];
    branch?: string;
    timestamp?: string;
    inputTranscription?: {
        text?: string;
        finished?: boolean;
    };
    outputTranscription?: {
        text?: string;
        finished?: boolean;
    };
    customMetadata?: {
        [k: string]: JsonValue;
    };
    candidateIndex?: number;
    modelVersion?: string;
    interactionId?: string;
    isCompacted?: boolean;
    startTime?: number;
    endTime?: number;
    compactedContent?: string;
    isScratchpad?: boolean;
    output?: JsonValue;
    route?: JsonValue;
    nodeInfo?: {
        path?: string;
        outputFor?: string[];
        messageAsOutput?: boolean;
    };
    isolationScope?: string;
}

export interface AdkNormalizerOptions {
    hostCompletion?: boolean;
    threadId?: string;
    invokeId?: string;
}

export interface AdkPart {
    text?: string;
    thought?: boolean;
    thoughtSignature?: string;
    functionCall?: {
        name: string;
        args?: {
            [k: string]: JsonValue;
        };
        id?: string | null;
    };
    functionResponse?: {
        name: string;
        response?: {
            [k: string]: JsonValue;
        };
        id?: string | null;
        thoughtSignature?: string;
    };
    inlineData?: {
        mimeType?: string;
        data?: string;
        displayName?: string;
    };
    executableCode?: {
        language?: string;
        code?: string;
    };
    codeExecutionResult?: {
        outcome?: string;
        output?: string;
    };
    fileData?: {
        mimeType?: string;
        fileUri?: string;
        displayName?: string;
    };
    mediaResolution?: JsonValue;
    videoMetadata?: JsonValue;
    toolCall?: JsonValue;
    toolResponse?: JsonValue;
    partMetadata?: JsonValue;
    audioTranscription?: JsonValue;
    mediaProcessing?: JsonValue;
    speechMetadata?: JsonValue;
}
